#!/usr/bin/env bash
# Date de naissance d'un mineur, 2/3 — front.
# - Profil du mineur : « Demander à mon parent de renseigner / corriger ma date de naissance » ;
# - page du parent /date-de-naissance-parent/<jeton> : renseigner, corriger ou effacer ;
# - alerte « date de majeur » à confirmer, sur cette page et sur celle de l'autorisation ;
# - fiche admin : « Passer majeur (justificatif vu) ». Pas de migration.
# Prérequis : apply-date-naissance-1-backend.sh.
# Usage (racine du repo) : bash apply-date-naissance-2-front.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/admin/users/legal/LegalStatusControl.tsx" 2>/dev/null | grep -qF "markAdultWithProof"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "model BirthDateRequest" "prisma/schema.prisma" 2>/dev/null || { echo "lancez d'abord apply-date-naissance-1-backend.sh"; exit 1; }
MODIFIED=("apps/web/src/app/robots.ts" "apps/web/src/features/admin/users/forms/update-me/UpdateMeForm.tsx" "apps/web/src/features/admin/users/legal/LegalStatusControl.tsx" "apps/web/src/features/image-consent/GuardianConsentPage.tsx")
CREATED=("apps/web/src/app/date-de-naissance-parent/[token]/page.tsx" "apps/web/src/features/image-consent/AskGuardianBirthDate.tsx" "apps/web/src/features/image-consent/BirthDateGuardianPage.tsx" "apps/web/src/features/image-consent/GuardianBirthDateField.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/src/app/date-de-naissance-parent/[token]" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "markAdultWithProof" "apps/web/src/features/admin/users/legal/LegalStatusControl.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/app/date-de-naissance-parent/[token]"
